        "Sarnia közvetlen csővezetéki összeköttetésben áll az albertai olajmezőkkel.",
        "A vegyipar a város legnagyobb foglalkoztatója több ezer szakemberrel.",
        "Itt fejlesztik az első növényi alapú bioműanyagokat kereskedelmi mennyiségben.",
        "A Szent Klára-folyó fontos vízi utat biztosít az alapanyagok szállításához.",
