    description: { de: "Eine römisch-katholische Basilika auf dem Mount Royal in Montreal.", hu: "Római katolikus bazilika a Mount Royalon, Montréalban.", ro: "O bazilică romano-catolică pe Muntele Royal din Montreal.", en: "A Roman Catholic minor basilica on Mount Royal in Montreal." },
