        "A szerkezet nem rendelkezik tartópillérekkel a folyóban (egynyílású híd).",
        "A piros és fehér színek Kanada zászlajára és Calgary zászlajára utalnak.",
        "Naponta átlagosan több mint 6000 gyalogos és kerékpáros használja.",
        "A spirális acélszerkezet súlya körülbelül 700 tonna.",
        "A tető edzett üvegből készült, amely megvédi a használókat az időjárástól.",
