        "Az épület öt emelet magas, és neoromán stílusjegyeket visel.",
        "A hátsó falán Derek Michael Besant festménye látható 1980 óta.",
        "Sir George Gooderham építtette, aki korának egyik leggazdagabb embere volt.",
        "Az épület éles csúcsa mindössze néhány méter széles.",
        "Toronto történelmi óvárosának (Old Town) szívében található.",
        "Ma irodaházként működik, és Kanada nemzeti történelmi helyszíne."
