        "Átlagos mélysége mindössze 100 méter, ami miatt hamar befagy.",
        "Henry Hudson angol felfedezőről nevezték el, aki 1610-ben hajózott be ide.",
        "Az öböl vize az Atlanti-óceán és a Jeges-tenger felé is összeköttetéssel bír.",
        "A partvidékén található a világ legdélebbi jegesmedve-populációja.",
        "Több mint 40 nagy folyó torkollik az öbölbe, jelentősen hígítva annak sótartalmát.",
        "A tengeri jég olvadása tavasszal és befagyása ősszel határozza meg a helyi klímát.",
        "A Hudson-öböl medencéje még ma is emelkedik a jégkorszaki jégtakaró súlyának megszűnése miatt."
