      "hu": "A Mount Waddington a Brit Kolumbiai Parti-hegység legmagasabb és legimpozánsabb csúcsa, amelyet gyakran „Rejtélyes Hegynek” is neveznek távoli és nehezen megközelíthető fekvése miatt. A 4019 méteres óriás a hegymászók egyik legnagyobb kihívása Kanadában, köszönhetően a szélsőséges időjárásnak, a hatalmas gleccsereknek és a technikailag nehéz sziklafalaknak. A hegyet körülvevő Waddington-hegység Kanada egyik legvadabb alpesi területe, ahol a jég és a szikla uralkodik. A csúcs elhelyezkedése miatt az óceán felől érkező viharok gyakran napokra vagy hetekre felhőkbe burkolják a hegyet, hatalmas mennyiségű havat zúdítva a gleccserekre. A hegy felfedezése viszonylag későn, csak a 20. század elején történt meg. Az alpesi eljegesedés formakincsének és a magashegységi éghajlat sajátosságainak tanulmányozása kiválóan kapcsolódik a K5-K8 tanterv természetismereti és földrajzi moduljaihoz.",
