      "hu": "A Mount Saint Elias (amelyet tévesen gyakran Mount Forakerként is említenek az azonos nevű alaszkai hegy miatt) Észak-Amerika egyik legimpozánsabb óriása a kanadai Yukon és az amerikai Alaszka határán. Ez a 5489 méteres csúcs különlegessége, hogy rendkívül közel fekszik az óceánhoz, így közvetlenül a tengerszintről emelkedik a magasba, ami az egyik legnagyobb relatív függőleges domborzatot eredményezi a világon. A hegyet hatalmas gleccserek és állandó hó borítja, időjárása pedig a Csendes-óceán közelsége miatt rendkívül viharos és kiszámíthatatlan. A Mount Saint Elias a Saint Elias-hegység része, amely a világ legmagasabb part menti hegylánca. A csúcs meghódítása a hegymászók számára a világ egyik legnehezebb feladata. A tektonikai lemezmozgások és a jégkorszaki maradványgleccserek vizsgálata kiválóan kapcsolódik a K5-K8 tanterv természetismereti és földrajzi moduljaihoz.",
