      "hu": "A Saint John-folyó (Wolastoq) New Brunswick tartomány fő ütőere, amelyet gyakran „Észak-Amerika Rajnájaként” emlegetnek festői szépsége és történelmi jelentősége miatt. A folyó több mint 670 kilométer hosszan folyik a szárazföld belsejéből a Fundy-öbölbe, útja során termékeny völgyeket, történelmi városokat és sűrű erdőket érintve. Legkülönlegesebb jelensége a torkolatnál található „Fordított vízesés” (Reversing Falls), ahol a Fundy-öböl extrém árapályszintje miatt a folyó vize naponta kétszer visszafelé kezd folyni. A folyó völgye az őslakos wolastoqiyik hazája, és később a lojalista telepesek fontos központja lett. A folyó menti táj ősszel, a fák színeződésekor a leglátványosabb. Az árapály-jelenség és a folyami ökoszisztémák kölcsönhatásának tanulmányozása kiválóan kapcsolódik a K5-K8 tanterv természetismereti és földrajzi moduljaihoz.",
