      "hu": "A Maligne-tó a Jasper Nemzeti Park ékköve, amely híres azúrkék vizéről és a közepén található ikonikus Spirit-szigetről. Ez a 22 kilométer hosszú tó a Kanadai-Sziklás-hegység leghosszabb természetes tava, amelyet fenséges gleccserek és hófedte csúcsok vesznek körül. A tó vize a környező gleccserek olvadékából származik, ami a benne lévő kőzetlisztnek köszönhetően nyeri el különleges türkizkék színét. A Spirit-sziget, amely valójában csak egy kis félsziget a tó távolabbi végén, Kanada egyik legtöbbet fotózott természeti látványossága. A környék gazdag élővilággal rendelkezik, gyakran látni grizzly medvéket, jávorszarvasokat és ritka harlekinrécéket a part mentén. A glaciális erózió és a tavak színének optikai magyarázata kiválóan kapcsolódik a K5-K8 tanterv természetismereti és földrajzi moduljaihoz.",
