      "hu": "Az Ezer-sziget (Thousand Islands) egy lenyűgöző archipelágó a Szent Lőrinc-folyó felső szakaszán, a kanadai Ontario és az amerikai New York állam határán. Valójában nem ezer, hanem több mint 1800 kisebb-nagyobb sziget alkotja ezt a vízi paradicsomot, melyek az ősi Kanadai Pajzs gránitkőzeteinek víz feletti maradványai. A tájat elegáns viktoriánus nyaralók, hatalmas kastélyok, mint a híres Boldt-kastély, és érintetlen természeti parkok teszik változatossá. A szigetvilág kristálytiszta vize népszerű a hajósok, horgászok és búvárok körében, utóbbiak számára a számos hajóroncs jelent különleges látnivalót. A terület UNESCO Bioszféra-rezervátum, ami kiemeli ökológiai jelentőségét. A folyami szigetvilág kialakulásának és a határokon átnyúló természetvédelmi területek kezelésének tanulmányozása kiválóan kapcsolódik a K5-K8 tanterv természetismereti és földrajzi moduljaihoz.",
